import Foundation
import RetroCore

/// Loads `ephemeris.json`, generated by `tools/ephemeris/generate_ephemeris.py`.
public enum BundledEphemeris {
    public enum LoadError: Error {
        case missingResource
        case unsupportedSchema(Int)
        case invalidCoverage
    }

    public static let supportedSchemaVersion = 1

    public static func load() throws -> Ephemeris {
        guard let url = Bundle.module.url(forResource: "ephemeris", withExtension: "json") else {
            throw LoadError.missingResource
        }
        return try decode(Data(contentsOf: url))
    }

    public static func decode(_ data: Data) throws -> Ephemeris {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom { decoder in
            let string = try decoder.singleValueContainer().decode(String.self)
            guard let date = parseMinute(string) else {
                throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Bad date \(string)"))
            }
            return date
        }
        let file = try decoder.decode(File.self, from: data)
        guard file.schemaVersion == supportedSchemaVersion else { throw LoadError.unsupportedSchema(file.schemaVersion) }
        guard let first = CalendarDay(iso: file.coverage.start), let last = CalendarDay(iso: file.coverage.end), first <= last else {
            throw LoadError.invalidCoverage
        }
        return Ephemeris(
            coverage: first...last,
            retrogrades: file.retrogrades.map {
                RetrogradePeriod(
                    planet: $0.planet, preShadowStart: $0.preShadowStart, stationRetrograde: $0.stationRetrograde,
                    stationDirect: $0.stationDirect, postShadowEnd: $0.postShadowEnd,
                    stationRetrogradeLongitude: $0.stationRetrogradeLongitude, stationDirectLongitude: $0.stationDirectLongitude
                )
            },
            ingresses: file.ingresses.map { SignIngress(planet: $0.planet, sign: $0.sign, time: $0.time, retrograde: $0.retrograde) },
            moonPhases: file.moonPhases.map { MoonPhaseEvent(phase: $0.phase, time: $0.time) },
            sources: file.sources.map { DataSource(name: $0.name, url: $0.url, use: $0.use) }
        )
    }

    /// Parses the file's `yyyy-MM-ddTHH:mmZ` UT timestamps.
    static func parseMinute(_ string: String) -> Date? {
        let fields = string.split(whereSeparator: { "-T:Z".contains($0) }).compactMap { Int($0) }
        guard fields.count == 5, string.hasSuffix("Z") else { return nil }
        return utc.date(from: DateComponents(year: fields[0], month: fields[1], day: fields[2], hour: fields[3], minute: fields[4]))
    }

    private static let utc: Calendar = {
        var c = Calendar(identifier: .gregorian)
        c.timeZone = TimeZone(identifier: "UTC")!
        return c
    }()

    // MARK: File format (schema version 1)

    private struct File: Decodable {
        struct Coverage: Decodable { let start: String; let end: String }
        struct Source: Decodable { let name: String; let url: URL; let use: String }
        struct Retrograde: Decodable {
            let planet: Planet
            let preShadowStart: Date
            let stationRetrograde: Date
            let stationDirect: Date
            let postShadowEnd: Date
            let stationRetrogradeLongitude: Double
            let stationDirectLongitude: Double
        }
        struct Ingress: Decodable { let planet: Planet; let sign: ZodiacSign; let time: Date; let retrograde: Bool }
        struct Moon: Decodable { let phase: MoonPhase; let time: Date }

        let schemaVersion: Int
        let coverage: Coverage
        let sources: [Source]
        let retrogrades: [Retrograde]
        let ingresses: [Ingress]
        let moonPhases: [Moon]
    }
}
